### Python

```python
# 计算一个数的因子2的个数
def count_factors_of_2(x: int) -> int:
    cnt = 0
    while x % 2 == 0:
        cnt += 1
        x //= 2
    return cnt

def solve():
    n = int(input())
    a = list(map(int, input().split()))

    # 原始每个数的因子2个数
    base = [count_factors_of_2(x) for x in a]
    total = sum(base)

    # 对每个数加1后，计算因子2个数的增量（非负）
    gains = []
    for x in a:
        orig = count_factors_of_2(x)
        new = count_factors_of_2(x + 1)
        gain = new - orig
        if gain > 0:
            gains.append(gain)
        else:
            gains.append(0)

    # 降序排序，取前两个增量
    gains.sort(reverse=True)
    max_increase = sum(gains[:2])  # 至多两次操作

    print(total + max_increase)

if __name__ == "__main__":
    solve()
```

